dashboard.definition:
{
 "title": "AI Agents",
 "description": "Agent runs, steps, tool calls, outcomes and guardrail activity across agentic workflows",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "time",
    "defaultValue": "-24h,now"
   }
  },
  "input_agent": {
   "type": "input.multiselect",
   "title": "Agent",
   "options": {
    "token": "agent",
    "defaultValue": "*",
    "items": [
     {
      "value": "*",
      "label": "All"
     }
    ]
   },
   "encoding": {
    "value": "primary.agent",
    "label": "primary.agent"
   },
   "dataSources": {
    "primary": "ds_agents"
   }
  },
  "input_outcome": {
   "type": "input.multiselect",
   "title": "Outcome",
   "options": {
    "token": "outcome",
    "defaultValue": "*",
    "items": [
     {
      "value": "*",
      "label": "All"
     }
    ]
   },
   "encoding": {
    "value": "primary.outcome",
    "label": "primary.outcome"
   },
   "dataSources": {
    "primary": "ds_outcomes"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$time.earliest$",
      "latest": "$time.latest$"
     }
    }
   }
  }
 },
 "dataSources": {
  "ds_agents": {
   "type": "ds.search",
   "options": {
    "query": "`ai_agent_runs` | stats count BY gen_ai.agent.name | rename gen_ai.agent.name AS agent | fields agent",
    "queryParameters": {
     "earliest": "-7d@d",
     "latest": "now"
    }
   },
   "name": "Agents"
  },
  "ds_outcomes": {
   "type": "ds.search",
   "options": {
    "query": "`ai_agent_runs` | stats count BY outcome | fields outcome",
    "queryParameters": {
     "earliest": "-7d@d",
     "latest": "now"
    }
   },
   "name": "Outcomes"
  },
  "ds_kpi_runs": {
   "type": "ds.search",
   "options": {
    "query": "`ai_kpi_agent_runs($agent$,$outcome$)`"
   },
   "name": "Agent Runs (24h)"
  },
  "ds_kpi_completion": {
   "type": "ds.search",
   "options": {
    "query": "`ai_kpi_task_completion($agent$)`"
   },
   "name": "Task Completion"
  },
  "ds_kpi_steps": {
   "type": "ds.search",
   "options": {
    "query": "`ai_kpi_avg_steps($agent$)`"
   },
   "name": "Avg Steps per Task"
  },
  "ds_kpi_tool_failures": {
   "type": "ds.search",
   "options": {
    "query": "`ai_kpi_tool_call_failures($agent$)`"
   },
   "name": "Tool Call Failures"
  },
  "ds_kpi_loops": {
   "type": "ds.search",
   "options": {
    "query": "`ai_kpi_runaway_loops($agent$)`"
   },
   "name": "Runaway Loops Stopped"
  },
  "ds_tool_calls": {
   "type": "ds.search",
   "options": {
    "query": "`ai_agent_steps` gen_ai.agent.name IN ($agent$) gen_ai.operation.name=execute_tool | timechart span=1h count BY gen_ai.tool.name useother=f | foreach * [eval <<FIELD>>=round('<<FIELD>>'/1000,2)]"
   },
   "name": "Tool Calls by Tool Over Time (thousands)"
  },
  "ds_completion_by_agent": {
   "type": "ds.search",
   "options": {
    "query": "`ai_agent_runs` gen_ai.agent.name IN ($agent$) | stats count AS total count(eval(outcome=\"completed\")) AS done BY gen_ai.agent.name | eval pct=round(100*done/total,1) | rename gen_ai.agent.name AS agent | sort - pct | table agent pct"
   },
   "name": "Task Completion by Agent (%)"
  },
  "ds_runs_table": {
   "type": "ds.search",
   "options": {
    "query": "`ai_agent_runs` gen_ai.agent.name IN ($agent$) outcome IN ($outcome$) | eval agent='gen_ai.agent.name', tool_calls=if(isnotnull(top_tool) AND top_tool_calls>10, tool_calls.\" (\".top_tool.\" x\".top_tool_calls.\")\", tool_calls), rank=case(trace_id=\"c41e77a09b3d\",0,outcome=\"loop_stopped\",1,outcome=\"blocked:guardrail\",2,outcome=\"escalated_to_human\",3,true(),4) | sort 0 rank -_time | fields - rank | head 50 | eval _time=strftime(_time,\"%Y-%m-%d %H:%M:%S.%3N\") | table _time agent trace_id steps tool_calls outcome tokens cost_usd"
   },
   "name": "Recent Agent Runs"
  }
 },
 "visualizations": {
  "viz_kpi_runs": {
   "type": "splunk.singlevalue",
   "title": "Agent Runs (24h)",
   "dataSources": {
    "primary": "ds_kpi_runs"
   },
   "options": {
    "backgroundColor": "transparent",
    "majorFontSize": 54,
    "numberPrecision": 0,
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "majorColor": "#FFFFFF"
   }
  },
  "viz_kpi_completion": {
   "type": "splunk.singlevalue",
   "title": "Task Completion",
   "dataSources": {
    "primary": "ds_kpi_completion"
   },
   "options": {
    "backgroundColor": "transparent",
    "majorFontSize": 54,
    "numberPrecision": 1,
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "majorColor": "> majorValue | rangeValue(colorCfg)",
    "unit": "%",
    "unitPosition": "after"
   },
   "context": {
    "colorCfg": [
     {
      "to": 90,
      "value": "#E0453A"
     },
     {
      "from": 90,
      "to": 95,
      "value": "#F8BE34"
     },
     {
      "from": 95,
      "value": "#53A051"
     }
    ]
   }
  },
  "viz_kpi_steps": {
   "type": "splunk.singlevalue",
   "title": "Avg Steps per Task",
   "dataSources": {
    "primary": "ds_kpi_steps"
   },
   "options": {
    "backgroundColor": "transparent",
    "majorFontSize": 54,
    "numberPrecision": 1,
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "majorColor": "#FFFFFF"
   }
  },
  "viz_kpi_tool_failures": {
   "type": "splunk.singlevalue",
   "title": "Tool Call Failures",
   "dataSources": {
    "primary": "ds_kpi_tool_failures"
   },
   "options": {
    "backgroundColor": "transparent",
    "majorFontSize": 54,
    "numberPrecision": 0,
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "majorColor": "> majorValue | rangeValue(colorCfg)"
   },
   "context": {
    "colorCfg": [
     {
      "to": 500,
      "value": "#53A051"
     },
     {
      "from": 500,
      "to": 2000,
      "value": "#F1813F"
     },
     {
      "from": 2000,
      "value": "#E0453A"
     }
    ]
   }
  },
  "viz_kpi_loops": {
   "type": "splunk.singlevalue",
   "title": "Runaway Loops Stopped",
   "dataSources": {
    "primary": "ds_kpi_loops"
   },
   "options": {
    "backgroundColor": "transparent",
    "majorFontSize": 54,
    "numberPrecision": 0,
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "majorColor": "> majorValue | rangeValue(colorCfg)"
   },
   "context": {
    "colorCfg": [
     {
      "to": 1,
      "value": "#53A051"
     },
     {
      "from": 1,
      "value": "#E0453A"
     }
    ]
   }
  },
  "viz_tool_calls": {
   "type": "splunk.column",
   "title": "Tool Calls by Tool Over Time (thousands)",
   "dataSources": {
    "primary": "ds_tool_calls"
   },
   "options": {
    "stackMode": "stacked",
    "legendDisplay": "bottom",
    "dataValuesDisplay": "off",
    "xAxisTitleText": "_time",
    "yAxisTitleText": "thousands",
    "seriesColors": [
     "#7B56DB",
     "#009CEB",
     "#00CDAF",
     "#DD9900",
     "#FF677B",
     "#CB2196"
    ]
   }
  },
  "viz_completion_by_agent": {
   "type": "splunk.bar",
   "title": "Task Completion by Agent (%)",
   "dataSources": {
    "primary": "ds_completion_by_agent"
   },
   "options": {
    "stackMode": "auto",
    "dataValuesDisplay": "all",
    "seriesColors": [
     "#009CEB"
    ],
    "legendDisplay": "off",
    "xAxisTitleText": "%",
    "yAxisTitleText": "",
    "xAxisMax": 100
   }
  },
  "viz_runs_table": {
   "type": "splunk.table",
   "title": "Recent Agent Runs",
   "dataSources": {
    "primary": "ds_runs_table"
   },
   "options": {
    "count": 50,
    "showRowNumbers": false,
    "headerVisibility": "fixed",
    "showInternalFields": false,
    "font": "monospace",
    "columnFormat": {
     "outcome": {
      "rowColors": "> table | seriesByName('outcome') | matchValue(outcomeCfg)"
     },
     "steps": {
      "rowColors": "> table | seriesByName('steps') | rangeValue(stepsCfg)",
      "align": "right",
      "width": 80
     },
     "cost_usd": {
      "align": "right",
      "width": 100
     },
     "tokens": {
      "align": "right",
      "width": 110
     }
    }
   },
   "context": {
    "outcomeCfg": [
     {
      "match": "completed",
      "value": "#53A051"
     },
     {
      "match": "loop_stopped",
      "value": "#E0453A"
     },
     {
      "match": "blocked:guardrail",
      "value": "#E0453A"
     },
     {
      "match": "escalated_to_human",
      "value": "#F1813F"
     },
     {
      "match": "abandoned",
      "value": "#F8BE34"
     }
    ],
    "stepsCfg": [
     {
      "to": 30,
      "value": "#FFFFFF"
     },
     {
      "from": 30,
      "value": "#E0453A"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "search": "`ai_gen_ai_idx` trace_id=\"$row.trace_id.value$\" | table _time sourcetype gen_ai.agent.name gen_ai.operation.name gen_ai.tool.name step_no status error_type outcome tokens cost_usd | sort 0 _time",
      "earliest": "$time.earliest$",
      "latest": "$time.latest$",
      "openInNewTab": true
     }
    }
   ]
  }
 },
 "layout": {
  "type": "grid",
  "options": {
   "width": 1440,
   "height": 850,
   "showTitleAndDescription": true
  },
  "globalInputs": [
   "input_time",
   "input_agent",
   "input_outcome"
  ],
  "structure": [
   {
    "item": "viz_kpi_runs",
    "type": "block",
    "position": {
     "x": 0,
     "y": 0,
     "w": 288,
     "h": 130
    }
   },
   {
    "item": "viz_kpi_completion",
    "type": "block",
    "position": {
     "x": 288,
     "y": 0,
     "w": 288,
     "h": 130
    }
   },
   {
    "item": "viz_kpi_steps",
    "type": "block",
    "position": {
     "x": 576,
     "y": 0,
     "w": 288,
     "h": 130
    }
   },
   {
    "item": "viz_kpi_tool_failures",
    "type": "block",
    "position": {
     "x": 864,
     "y": 0,
     "w": 288,
     "h": 130
    }
   },
   {
    "item": "viz_kpi_loops",
    "type": "block",
    "position": {
     "x": 1152,
     "y": 0,
     "w": 288,
     "h": 130
    }
   },
   {
    "item": "viz_tool_calls",
    "type": "block",
    "position": {
     "x": 0,
     "y": 130,
     "w": 720,
     "h": 320
    }
   },
   {
    "item": "viz_completion_by_agent",
    "type": "block",
    "position": {
     "x": 720,
     "y": 130,
     "w": 720,
     "h": 320
    }
   },
   {
    "item": "viz_runs_table",
    "type": "block",
    "position": {
     "x": 0,
     "y": 450,
     "w": 1440,
     "h": 400
    }
   }
  ]
 }
}
